/** A library icon. `size` defaults to the viewBox size (18 or 20 in the library). */
export function Icon({ name, size, className, title }: { name: IconName; size?: number; className?: string; title?: string }): ReactNode {
  if (name === "battery") return <BatteryIcon percent={100} size={size} className={className} />;
  const def = ICONS[name];
  const s = size ?? Number(def.viewBox.split(" ")[2]);
  return (
    <svg className={className} width={s} height={s} viewBox={def.viewBox} fill="none" xmlns="http://www.w3.org/2000/svg"
      aria-hidden={title ? undefined : true} role={title ? "img" : undefined}>
      {title ? <title>{title}</title> : null}
      {def.body}
    </svg>
  );
}

/** Icon/battery with a live fill level: grey shell; the level bar is warning
    yellow when charging (with a bolt) or at 35% and below — as on Ivan's
    reference screens (35% and "75% Charging" both yellow) — white otherwise. */
export function BatteryIcon({ percent, charging = false, size = 18, className }: { percent: number; charging?: boolean; size?: number; className?: string }): ReactNode {
  const p = Math.max(0, Math.min(100, percent));
  const w = Math.max(0.6, (p / 100) * 10.5);
  const fill = charging || p <= 35 ? "var(--mk-warning)" : "var(--mk-text)";
  return (
    <svg className={className} width={size} height={size} viewBox="0 0 18 18" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
      <path d="M17.25 7H16.5V6.25C16.5 4.733 15.267 3.5 13.75 3.5H3.75C2.233 3.5 1 4.733 1 6.25V11.75C1 13.267 2.233 14.5 3.75 14.5H13.75C15.267 14.5 16.5 13.267 16.5 11.75V11H17.25C17.664 11 18 10.664 18 10.25V7.75C18 7.336 17.664 7 17.25 7ZM15 11.75C15 12.439 14.439 13 13.75 13H3.75C3.061 13 2.5 12.439 2.5 11.75V6.25C2.5 5.561 3.061 5 3.75 5H13.75C14.439 5 15 5.561 15 6.25V11.75Z" fill="#B7B7B8" />
      <rect x="4" y="6.5" width={w} height="5" rx="0.6" fill={fill} />
      {charging ? <path d="M9.6 5.6 7.4 9.3h1.9l-.5 3.1 2.6-4h-1.9l.6-2.8Z" fill="#0e1011" /> : null}
    </svg>
  );
}
